  tx.timelock <= at.local.timestamp + HTLC_ENFORCEMENT_RESERVE_MS || tx.revealBeforeHeight <= at.local.jHeight
  || at.f.timestamp >= tx.timelock || tx.revealBeforeHeight <= at.f.jHeight;
